/**
 * L'année du cours d'une entreprise, sous la forme de l'année jouée par l'arène (`anneeJouee`) :
 * les trimestres de l'entreprise de l'élève (« joueur ») et son état de départ. Les concurrents n'y
 * sont pas : un chapitre qui les lit reste sur l'arène tant qu'il n'est pas passé sur le monde.
 */
export function anneeDuCours(code: string) {
  const a = ANNEES[code];
  if (!a) throw new Error(`Pas d'année du cours pour l'entreprise ${code}`);
  return { depart: a.depart, partie: { rounds: a.trimestres.map((joueur) => ({ results: { joueur: joueur as CompanyRoundResult } as Record<string, CompanyRoundResult> })) } };
}
